from lxml import etree
from odoo.tests import tagged
from odoo.tests.common import TransactionCase


@tagged("post_install", "-at_install")
class TestUserGroupsView(TransactionCase):
    """The user groups view is regenerated by code each time a group changes. The portal backend groups must be
    moved to their own block regardless of the language of the user that triggers the regeneration.
    """

    @classmethod
    def setUpClass(cls):
        super().setUpClass()
        cls.category_advanced = cls.env.ref("portal_backend.category_portal_advanced")
        cls.group_portal_backend = cls.env.ref("portal_backend.group_portal_backend")
        # an app of the advanced portal (like portal_holidays), so the "Advanced Portal" block exists in the view
        cls.category_app = cls.env["ir.module.category"].create(
            {"name": "Test Portal App", "parent_id": cls.category_advanced.id}
        )

    def _create_app_group(self, lang):
        return (
            self.env["res.groups"]
            .with_context(lang=lang)
            .create({"name": "Test Portal App User", "category_id": self.category_app.id})
        )

    def _assert_advanced_portal_block_moved(self):
        view = self.env.ref("base.user_groups_view").with_context(lang=None)
        arch = etree.fromstring(view.arch)
        blocks = arch.xpath("//group[@string='Advanced Portal']")
        self.assertEqual(len(blocks), 1, "The Advanced Portal block must be in the view")
        self.assertTrue(
            blocks[0].getparent().get("invisible", "").endswith(f"!= {self.group_portal_backend.id}"),
            "The Advanced Portal block must only be visible for portal backend users",
        )

    def test_portal_backend_groups_moved_with_translated_language(self):
        self.env["res.lang"]._activate_lang("es_AR")
        self.category_advanced.with_context(lang="es_AR").name = "Portal Avanzado"

        self._create_app_group("es_AR")

        self._assert_advanced_portal_block_moved()

    def test_portal_backend_groups_moved_without_language(self):
        self._create_app_group(None)

        self._assert_advanced_portal_block_moved()
